mapper.select:
SELECT tt.id, tt.number, tt.name, tt.content, tt.system_name, tt.module, tt.business_type, tt.status, tt.level, tt.urgent, tt.approval_type, tt.url,tt.url_open_type, tt.approval_url, tt.creator_name, tt.creator_id_card, tt.creator_department, tt.creator_department_id, tt.creator_department_code, tt.start_time, tt.end_time, tt.complete_time, tt.extend, tt.operate_time, tt.update_time, tt.type FROM tb_tasks tt WHERE tt.business_type IS NOT NULL AND tt.status IS NOT NULL AND tt.status != '已作废'
AND EXISTS (SELECT 1 FROM tb_tasks_executors te WHERE tt.id = te.task_id AND te.id_card = #{idCard})
and start_time >= #{startTime}
and start_time <= #{endTime}

SELECT tt.business_type as type,count(1) as count FROM tb_tasks tt
WHERE tt.system_name IS NOT NULL
AND tt.status IS NOT NULL
AND tt.status != '已作废'

    AND EXISTS (SELECT 1 FROM tb_tasks_executors te WHERE tt.id = te.task_id AND te.id_card = #{idCard})


    and start_time >= #{startTime}


    and start_time <= #{endTime}

group by tt.business_type
order by count desc
limit #{limit}

SELECT tt.id, tt.number, tt.name, tt.content, tt.system_name, tt.module, tt.business_type, tt.status, tt.level, tt.urgent, tt.approval_type, tt.url,tt.url_open_type, tt.approval_url, tt.creator_name, tt.creator_id_card, tt.creator_department, tt.creator_department_id, tt.creator_department_code, tt.start_time, tt.end_time, tt.complete_time, tt.extend, tt.operate_time, tt.update_time, tt.type FROM tb_tasks tt WHERE tt.business_type IS NOT NULL AND tt.status = '待处理'
AND EXISTS (SELECT 1 FROM tb_tasks_executors te WHERE tt.id = te.task_id AND te.id_card = #{idCard})
and tt.start_time >= #{startTime}
and tt.start_time <= #{endTime}

SELECT tt.id, tt.number, tt.name, tt.content, tt.system_name, tt.module,
       tt.business_type, tt.status, tt.level, tt.urgent, tt.approval_type, tt.url,tt.url_open_type,
       tt.approval_url, tt.creator_name, tt.creator_id_card, tt.creator_department,
       tt.creator_department_id, tt.creator_department_code, tt.start_time, tt.end_time,
       tt.complete_time, tt.extend, tt.operate_time, tt.update_time, tt.type
FROM tb_tasks tt
WHERE tt.business_type IS NOT NULL
AND tt.status IS NOT NULL
AND tt.status != '已作废'

    AND (
    tt.creator_department_code IN

        #{orgCode}

    OR EXISTS (
    SELECT 1 FROM tb_tasks_executors te WHERE tt.id = te.task_id AND te.department_code IN
    #{orgCode}

    )
    )


    and start_time >= #{startTime}


    and start_time <= #{endTime}

SELECT tt.id, tt.number, tt.name, tt.content, tt.system_name, tt.module, tt.business_type, tt.status, tt.level, tt.urgent, tt.approval_type, tt.url,tt.url_open_type, tt.approval_url, tt.creator_name, tt.creator_id_card, tt.creator_department, tt.creator_department_id, tt.creator_department_code, tt.start_time, tt.end_time, tt.complete_time, tt.extend, tt.operate_time, tt.update_time, tt.type FROM tb_tasks tt
AND (tt.name LIKE concat('%',#{tasksQueryReq.keywords},'%') OR tt.content LIKE concat('%',#{tasksQueryReq.keywords},'%') OR tt.system_name LIKE concat('%',#{tasksQueryReq.keywords},'%') OR tt.creator_name LIKE concat('%',#{tasksQueryReq.keywords},'%') OR tt.creator_department LIKE concat('%',#{tasksQueryReq.keywords},'%') )
AND EXISTS (SELECT 1 FROM tb_tasks_executors te WHERE tt.id = te.task_id AND te.id_card = #{tasksQueryReq.executor})
AND EXISTS (SELECT 1 FROM tb_tasks_executors te WHERE tt.id = te.task_id AND te.id_card = #{tasksQueryReq.idCard})
AND tt.start_time >= #{tasksQueryReq.startTime} AND tt.start_time <= #{tasksQueryReq.endTime}
AND tt.status =#{tasksQueryReq.status}
AND tt.business_type IN
#{businessType}
AND tt.level IN
#{level}
AND tt.urgent =#{tasksQueryReq.urgent}
ORDER BY tt.update_time DESC
